import React, { useMemo, useState } from 'react';
import { getAuthToken } from '../services/authStorage';

const initialForm = {
  agent_name: '',
  agent_number: '',
  store_number: '',
  business_owner_name: '',
  contact_phone: '',
  id_number: '',
  business_location: '',
  date_visited: new Date().toISOString().slice(0, 10),
  registration_date: '',
  admin_name: '',
  witness_name: '',
  witness_id_number: '',
  witness_phone: '',
  customer_type: '',
  outcome: '',
  visit_mode: 'field_visit',
  heard_about_okoa: '',
  interested_in_okoa: '',
  already_uses_okoa: '',
  new_client: true,
  customers_visited: '',
  registered_count: '',
  appointment_count: '',
  undecided_count: '',
  not_interested_count: '',
  referral_count: '',
  referral_details: '',
  follow_up_details: '',
  contract_status: 'pending',
  notes: '',
  commission_statement: 'false',
  kra_pin: 'false',
  national_id: 'false',
  business_permit: 'false',
  contract: 'false',
  incorporation_certificate: 'false',
  company_kra_pin: 'false',
  cr12: 'false',
};

const documentFields = {
  sub_agent: [
    ['business_permit', 'Business permit'], ['kra_pin', 'Individual KRA PIN'],
    ['commission_statement', 'Six-month commission statement'], ['contract', 'Agent and sub-agent contract'],
    ['national_id', 'Owner national ID'],
  ],
  agent: [
    ['incorporation_certificate', 'Certificate of incorporation / registration'], ['company_kra_pin', 'Company or owner KRA PIN'],
    ['commission_statement', 'Six-month commission statement'], ['national_id', 'Owner / director national IDs'], ['cr12', 'CR12 for directors'],
  ],
};

export default function SalesDailyReportForm({ onSubmitted }) {
  const [form, setForm] = useState(initialForm);
  const [documents, setDocuments] = useState([]);
  const [reportMode, setReportMode] = useState('daily');
  const [csvFile, setCsvFile] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [feedback, setFeedback] = useState(null);

  const summaryText = useMemo(() => {
    const lines = [
      `Area/region visited: ${form.business_location || 'Not stated'}`,
      `Customers visited: ${form.customers_visited || '0'}`,
      `New client: ${form.new_client ? 'Yes' : 'No'}`,
      `Heard about Okoa Float: ${form.heard_about_okoa || 'Not stated'}`,
      `Interested in using Okoa Float: ${form.interested_in_okoa || 'Not stated'}`,
      `Already using Okoa Float: ${form.already_uses_okoa || 'Not stated'}`,
      `Registered: ${form.registered_count || '0'}`,
      `Appointments: ${form.appointment_count || '0'}`,
      `Undecided: ${form.undecided_count || '0'}`,
      `Not interested: ${form.not_interested_count || '0'}`,
      `Referrals: ${form.referral_count || '0'}`,
      `Customer feedback: ${form.notes || 'None provided'}`,
    ];
    return lines.join(' | ');
  }, [form]);

  const update = (name, value) => setForm((current) => ({ ...current, [name]: value }));

  const toggleDocument = (name) => {
    setForm((current) => ({
      ...current,
      [name]: current[name] === 'true' ? 'false' : 'true',
    }));
  };

  const handleFiles = (event) => {
    setDocuments(Array.from(event.target.files || []));
  };

  const importCsv = async (event) => {
    event.preventDefault();
    if (!csvFile) return;
    setSubmitting(true);
    setFeedback(null);
    try {
      const body = new FormData();
      body.append('file', csvFile);
      const response = await fetch('/api/sales/reports/import', { method: 'POST', headers: { Authorization: `Bearer ${getAuthToken()}` }, body });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.error?.message || payload.data?.errors?.map((item) => `Row ${item.row}: ${item.message}`).join('; ') || 'Unable to import CSV.');
      setCsvFile(null);
      event.target.reset();
      setFeedback({ type: 'success', text: payload.message || 'Reports imported successfully.' });
    } catch (error) {
      setFeedback({ type: 'error', text: error.message });
    } finally {
      setSubmitting(false);
    }
  };

  const submit = async (event) => {
    event.preventDefault();
    setSubmitting(true);
    setFeedback(null);

    try {
      const body = new FormData();
      Object.entries(form).forEach(([name, value]) => body.append(name, value));
      body.set('notes', summaryText);
      documents.forEach((file) => body.append('documents', file));

      const response = await fetch('/api/sales/reports', {
        method: 'POST',
        headers: { Authorization: `Bearer ${getAuthToken()}` },
        body,
      });

      const payload = await response.json();
      if (!response.ok) {
        throw new Error(payload.error?.message || 'Unable to submit daily report.');
      }

      setForm({ ...initialForm, date_visited: new Date().toISOString().slice(0, 10) });
      setDocuments([]);
      setFeedback({ type: 'success', text: payload.message || 'Daily sales report submitted.' });
      if (onSubmitted) onSubmitted(payload.data);
    } catch (error) {
      setFeedback({ type: 'error', text: error.message });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <section className="leave-section sales-report-section" id="sales-daily-report">
      <div className="leave-section-heading">
        <div>
          <p className="leave-kicker">SALES AND MARKETING</p>
          <h2>Daily sales report</h2>
          <p className="leave-muted">Track field visits, customer feedback, registrations, appointments, and referrals.</p>
        </div>
      </div>

      <div className="report-view-tabs sales-report-mode-tabs" role="tablist" aria-label="Report entry mode">
        <button type="button" className={reportMode === 'daily' ? 'is-active' : ''} onClick={() => setReportMode('daily')}>Daily report</button>
        <button type="button" className={reportMode === 'csv' ? 'is-active' : ''} onClick={() => setReportMode('csv')}>CSV upload</button>
      </div>

      {feedback && (
        <div className={`leave-alert ${feedback.type}`} role="status">
          {feedback.text}
        </div>
      )}

      {reportMode === 'csv' ? (
        <form className="sales-report-form sales-csv-form" onSubmit={importCsv}>
          <div className="sales-upload-copy"><strong>Import multiple daily reports</strong><span>Use the template, complete one report per row, then upload the CSV.</span></div>
          <div className="form-actions"><a className="leave-secondary-button" href="/api/sales/reports/template" download>Download CSV template</a><label className="file-picker">Choose CSV<input type="file" accept=".csv,text/csv" onChange={(event) => setCsvFile(event.target.files?.[0] || null)} required /></label><button type="submit" disabled={submitting || !csvFile}>{submitting ? 'Importing...' : 'Import reports'}</button></div>
        </form>
      ) : <form className="sales-report-form" onSubmit={submit}>
        <div className="sales-report-grid">
          <label>
            Agent name
            <input value={form.agent_name} onChange={(event) => update('agent_name', event.target.value)} required />
          </label>
          <label>
            Agent number
            <input value={form.agent_number} onChange={(event) => update('agent_number', event.target.value)} />
          </label>
          <label>
            Store number
            <input value={form.store_number} onChange={(event) => update('store_number', event.target.value)} />
          </label>
          <label>
            Business owner name
            <input value={form.business_owner_name} onChange={(event) => update('business_owner_name', event.target.value)} />
          </label>
          <label>
            Contact / phone number
            <input value={form.contact_phone} onChange={(event) => update('contact_phone', event.target.value)} />
          </label>
          <label>
            ID number
            <input value={form.id_number} onChange={(event) => update('id_number', event.target.value)} />
          </label>
          <label>
            Business location / area visited
            <input value={form.business_location} onChange={(event) => update('business_location', event.target.value)} required />
          </label>
          <label>
            Date visited
            <input type="date" value={form.date_visited} onChange={(event) => update('date_visited', event.target.value)} required />
          </label>
          <label>
            Registration date
            <input type="date" value={form.registration_date} onChange={(event) => update('registration_date', event.target.value)} />
          </label>
          <label>
            Admin
            <input value={form.admin_name} onChange={(event) => update('admin_name', event.target.value)} />
          </label>
          <label>
            Witness name
            <input value={form.witness_name} onChange={(event) => update('witness_name', event.target.value)} />
          </label>
          <label>
            Witness ID number
            <input value={form.witness_id_number} onChange={(event) => update('witness_id_number', event.target.value)} />
          </label>
          <label>
            Witness phone
            <input value={form.witness_phone} onChange={(event) => update('witness_phone', event.target.value)} />
          </label>
          <label>
            Customer type
            <select value={form.customer_type} onChange={(event) => update('customer_type', event.target.value)} required>
              <option value="">Select type</option>
              <option value="agent">Agent / M-Pesa dealer</option>
              <option value="sub_agent">Sub-agent</option>
            </select>
          </label>
          <label>
            Visit outcome
            <select value={form.outcome} onChange={(event) => update('outcome', event.target.value)} required>
              <option value="">Select outcome</option>
              <option value="registered">Registered</option>
              <option value="appointment">Appointment requested</option>
              <option value="undecided">Undecided</option>
              <option value="promised">Promised to adopt later</option>
              <option value="declined">Declined</option>
            </select>
          </label>
          <label>
            Visit mode
            <select value={form.visit_mode} onChange={(event) => update('visit_mode', event.target.value)}>
              <option value="field_visit">Field visit</option>
              <option value="telesales">Telesales</option>
            </select>
          </label>
        </div>

        <div className="sales-report-grid" style={{ gridTemplateColumns: 'repeat(2, minmax(0, 1fr))' }}>
          <label>
            Number of clients visited
            <input type="number" min="0" value={form.customers_visited} onChange={(event) => update('customers_visited', event.target.value)} />
          </label>
          <label>
            Number registered
            <input type="number" min="0" value={form.registered_count} onChange={(event) => update('registered_count', event.target.value)} />
          </label>
          <label>
            Number requested appointment
            <input type="number" min="0" value={form.appointment_count} onChange={(event) => update('appointment_count', event.target.value)} />
          </label>
          <label>
            Number undecided
            <input type="number" min="0" value={form.undecided_count} onChange={(event) => update('undecided_count', event.target.value)} />
          </label>
          <label>
            Number not interested
            <input type="number" min="0" value={form.not_interested_count} onChange={(event) => update('not_interested_count', event.target.value)} />
          </label>
          <label>
            Number of referrals obtained
            <input type="number" min="0" value={form.referral_count} onChange={(event) => update('referral_count', event.target.value)} />
          </label>
        </div>

        <div className="sales-report-grid" style={{ gridTemplateColumns: 'repeat(2, minmax(0, 1fr))' }}>
          <label>
            Have they heard of Okoa Float before?
            <select value={form.heard_about_okoa} onChange={(event) => update('heard_about_okoa', event.target.value)}>
              <option value="">Select</option>
              <option value="Yes">Yes</option>
              <option value="No">No</option>
              <option value="Not sure">Not sure</option>
            </select>
          </label>
          <label>
            Are they interested in using the service?
            <select value={form.interested_in_okoa} onChange={(event) => update('interested_in_okoa', event.target.value)}>
              <option value="">Select</option>
              <option value="Yes">Yes</option>
              <option value="No">No</option>
              <option value="Undecided">Undecided</option>
            </select>
          </label>
          <label>
            Are they already using Okoa Float?
            <select value={form.already_uses_okoa} onChange={(event) => update('already_uses_okoa', event.target.value)}>
              <option value="">Select</option>
              <option value="Yes">Yes</option>
              <option value="No">No</option>
            </select>
          </label>
          <label>
            Existing customer or new client
            <select value={String(form.new_client)} onChange={(event) => update('new_client', event.target.value === 'true')}>
              <option value="true">New client</option>
              <option value="false">Existing client</option>
            </select>
          </label>
        </div>

        <fieldset className="sales-documents">
          <legend>Documents submitted</legend>
          <div className="sales-checkbox-grid">
            {(documentFields[form.customer_type] || []).map(([name, label]) => (
              <label key={name}>
                <input
                  type="checkbox"
                  checked={form[name] === 'true'}
                  onChange={() => toggleDocument(name)}
                />
                {label}
              </label>
            ))}
          </div>
        </fieldset>

        <label>
          Optional supporting documents
          <input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.csv" onChange={handleFiles} />
        </label>

        <label>
          Customer feedback / remarks
          <textarea
            rows="5"
            value={form.notes}
            onChange={(event) => update('notes', event.target.value)}
            placeholder="Record customer feedback, referrals, appointment details, or any remarks..."
          />
        </label>

        <div className="sales-report-grid">
          <label>Referral details<textarea rows="3" value={form.referral_details} onChange={(event) => update('referral_details', event.target.value)} placeholder="Names or contacts of referrals" /></label>
          <label>Follow-up / appointment details<textarea rows="3" value={form.follow_up_details} onChange={(event) => update('follow_up_details', event.target.value)} placeholder="Appointments, undecided clients, and next actions" /></label>
        </div>
        <p className="sales-report-helper">Registered clients must provide the checklist above. Documents should also be sent to info@okoafloat.com and the client will sign an electronic contract.</p>

        <div className="form-actions">
          <button type="submit" disabled={submitting}>
            {submitting ? 'Submitting report...' : 'Submit daily report'}
          </button>
        </div>
      </form>}
    </section>
  );
}
